using System.Text;using Microsoft.AspNetCore.Authentication.JwtBearer;using Microsoft.IdentityModel.Tokens;using Microsoft.OpenApi.Models;using NexHire.Application.Interfaces.Repositories;using NexHire.Application.Interfaces.Services;using NexHire.Application.Services;using NexHire.Infrastructure.Authentication;using NexHire.Infrastructure.Repositories;
namespace NexHire.API.Extensions;
public static class AuthenticationExtensions
{
    public static IServiceCollection AddNexHireAuthentication(this IServiceCollection services,IConfiguration config){services.AddScoped<IUserRepository,UserRepository>();services.AddScoped<IAuthService,AuthService>();services.AddScoped<IPasswordHasher,PasswordHasher>();services.AddScoped<ITokenService,JwtTokenGenerator>();var key=Encoding.UTF8.GetBytes(config["Jwt:Key"]??throw new InvalidOperationException("Jwt:Key missing."));services.AddAuthentication(JwtBearerDefaults.AuthenticationScheme).AddJwtBearer(o=>o.TokenValidationParameters=new(){ValidateIssuer=true,ValidateAudience=true,ValidateLifetime=true,ValidateIssuerSigningKey=true,ValidIssuer=config["Jwt:Issuer"],ValidAudience=config["Jwt:Audience"],IssuerSigningKey=new SymmetricSecurityKey(key),ClockSkew=TimeSpan.Zero});return services;}
    public static void AddJwtSwagger(this Swashbuckle.AspNetCore.SwaggerGen.SwaggerGenOptions o){o.AddSecurityDefinition("Bearer",new(){Name="Authorization",Type=SecuritySchemeType.Http,Scheme="bearer",BearerFormat="JWT",In=ParameterLocation.Header});o.AddSecurityRequirement(new(){{new(){Reference=new(){Type=ReferenceType.SecurityScheme,Id="Bearer"}},Array.Empty<string>()}});}
}
